#include "WorldCandidateManifest.h"
#include "json.hpp"
#include <stdexcept>
namespace Silver::WorldEditor
{
std::vector<std::uint8_t> WorldCandidateManifest::Encode()const{nlohmann::json terrain=nlohmann::json::array(),sidecars=nlohmann::json::array();for(const auto&[name,sha]:TerrainBaselines)terrain.push_back({{"name",name},{"sha256",sha}});for(const auto&[name,sha]:Sidecars)sidecars.push_back({{"name",name},{"sha256",sha}});nlohmann::json j{{"schema",Schema},{"mapId",MapId},{"worldNumber",WorldNumber},{"objectBaselineSha256",ObjectBaselineSha256},{"openMuBaselineSha256",OpenMuBaselineSha256},{"terrainBaselines",terrain},{"sidecars",sidecars}};auto text=j.dump(2)+"\n";return{text.begin(),text.end()};}
WorldCandidateManifest WorldCandidateManifest::Decode(std::span<const std::uint8_t>b){if(b.empty()||b.size()>256*1024)throw std::invalid_argument("Candidate manifest fuera de limites.");nlohmann::json j;try{j=nlohmann::json::parse(std::string(reinterpret_cast<const char*>(b.data()),b.size()));}catch(const nlohmann::json::exception&){throw std::invalid_argument("Candidate manifest JSON invalido.");}if(j.value("schema","")!=Schema)throw std::invalid_argument("Candidate manifest schema incompatible.");WorldCandidateManifest m;m.MapId=j.value("mapId",-1);m.WorldNumber=j.value("worldNumber",-1);m.ObjectBaselineSha256=j.value("objectBaselineSha256","");m.OpenMuBaselineSha256=j.value("openMuBaselineSha256","");if(m.MapId<0||m.WorldNumber<0||m.ObjectBaselineSha256.size()!=64)throw std::invalid_argument("Candidate manifest incompleto.");for(const auto&x:j.value("terrainBaselines",nlohmann::json::array())){auto n=x.value("name",""),s=x.value("sha256","");if(n.empty()||s.size()!=64)throw std::invalid_argument("Terrain fingerprint invalido.");m.TerrainBaselines.emplace_back(std::move(n),std::move(s));}for(const auto&x:j.value("sidecars",nlohmann::json::array())){auto n=x.value("name",""),s=x.value("sha256","");if(n.empty()||s.size()!=64)throw std::invalid_argument("Sidecar fingerprint invalido.");m.Sidecars.emplace_back(std::move(n),std::move(s));}return m;}
}
